import{_ as a,o as n,a as p,b as c}from"./app.C41L12d5.js";const e="/ascendc.github.io/assets/mmad_kdirectionalign.DR-Uru_Z.png",t="/ascendc.github.io/assets/kdirectionalign_k_is36.BHk_3PcO.png",i="/ascendc.github.io/assets/kdirectionalign_k_is36_false.BkvIrmOc.png",l="/ascendc.github.io/assets/kdirectionalign_demo.7C7bxsad.png",I=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"Mmad计算关键特性说明","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/mmad_compute_key_features"},{"text":"K方向对齐约束","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/k_direction_alignment_constraint"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/k_direction_alignment_constraint.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/k_direction_alignment_constraint.md","lastUpdated":1785832713000}'),r={name:"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/k_direction_alignment_constraint.md"};function _(o,s,m,d,A,u){return n(),p("div",null,[...s[0]||(s[0]=[c('<div><article class="markdown-body"><h1>K方向对齐约束<span id="ZH-CN_TOPIC_0000002569070973"></span></h1><p><strong>特性说明：</strong></p><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品/Atlas A3 训练系列产品/Atlas A3 推理系列产品，Mmad接口支持开启此特性。</p><div data-filter="950"><p>Ascend 950PR/Ascend 950DT产品上L0A Buffer为NZ排布，非ZZ排布，A矩阵转置非对齐float数据类型场景，L0A Buffer在K方向8对齐，无需开启此特性去确保计算正确性。</p></div><p>K方向对齐的核心功能是通过kDirectionAlign参数控制在使用float数据类型（其他数据类型无需关注此特性）时，L0A Buffer和L0B Buffer矩阵在K方向上的对齐方式。</p><p>当设置mmadParams.kDirectionAlign = true时，L0A Buffer/L0B Buffer中的矩阵会将K方向对齐到 `ceil(K/16)*16`。</p><p><img src="'+e+'" alt="K方向对齐示意图"></p><p>例如，当K=44和K=36时，都会被对齐到48。在这种情况下，对于K=44，L0A Buffer/L0B Buffer中的12个分形块都会被完整读入CUBE；而对于K=36的情况，虽然对齐后也是48，但只有其中的10个分形块会被读入CUBE。</p><p><img src="'+t+'" alt="K方向对齐到48示意图"></p><p>当设置 `mmadParams.kDirectionAlign = false`时，L0A Buffer/L0B Buffer中的矩阵会将K方向对齐到 `ceil(K/8)*8`。</p><p>例如，当K=44时对齐到48，而K=36时对齐到40。在这种情况下，对于K=44，L0A Buffer/L0B Buffer中的12个分形块都会被完整读入CUBE；而对于K=36的情况，L0A Buffer/L0B Buffer中的10个分形块都会被读取到CUBE中。</p><p><img src="'+i+'" alt="K方向对齐到40示意图"></p><ol><li><p>A矩阵非转置的场景，无需开启kDirectionAlign。</p></li><li><p>A矩阵转置的场景，需要开启kDirectionAlign。</p></li></ol><p>当输入需要进行转置操作时，例如原始矩阵A的维度为K×M，在搬入L1 Buffer后，其存储形式会变为NZ排布（本质上仍为K×M）。此时应调用具备转置能力的LoadData接口。该接口的内部实现如下图所示：在K方向上会进行16的对齐处理（如左图所示）。完成转置后，数据将呈现出如右图所示的ZZ分形形式，存储在L0A Buffer中。为了避免读入无效数据，可以通过开启kDirectionAlign参数，仅读取有效分形的数据。</p><p><img src="'+l+`" alt="K方向对齐转置示意图"></p><p><strong>使用示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">MmadParams</span><span class="w"> </span><span class="n">mmadParams</span><span class="p">;</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">m</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">m</span><span class="p">;</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">n</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">n</span><span class="p">;</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">k</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">k</span><span class="p">;</span>
<span class="c1">// 设置float数据类型下K方向对齐到ceil(K/16)*16</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">kDirectionAlign</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Mmad</span><span class="p">(</span><span class="n">c</span><span class="p">,</span><span class="w"> </span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="n">mmadParams</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const g=a(r,[["render",_]]);export{I as __pageData,g as default};
